def which_lever(need):
    return {
        "fresh or citable knowledge": "RAG",
        "consistent style or output format": "fine-tune",
        "small stable corpus that fits the window": "long-context",
    }[need]

print(which_lever("fresh or citable knowledge"))   # RAG
print(which_lever("consistent style or output format"))  # fine-tune
# the lever follows from the NEED, not from what's trendy
